import os,time,hashlib,random,smtplib
from email.mime.text import MIMEText

SECRET="nik_secret_key"
SCRIPT_ID="3a709bed-4c58-4481-ae41-620a57025e1d"
LICENSE_FILE=os.path.expanduser("~/.lic_data")

SENDER_EMAIL="faddebaazyoussef@gmail.com"
APP_PASSWORD="kmkpqxjviwmqahok"
RECEIVER_EMAIL="ajayaryan743@gmail.com"

def send_email(code):
    msg=MIMEText(f"Your activation code is: {code}")
    msg["Subject"]="Tool Activation Code"
    msg["From"]=SENDER_EMAIL
    msg["To"]=RECEIVER_EMAIL

    s=smtplib.SMTP("smtp.gmail.com",587)
    s.starttls()
    s.login(SENDER_EMAIL,APP_PASSWORD)
    s.send_message(msg)
    s.quit()

def generate_code():
    return str(random.randint(100000,999999))

def save_license():
    expiry=str(int(time.time()+365*86400))
    raw=expiry+"|"+SECRET+"|"+SCRIPT_ID
    sig=hashlib.sha256(raw.encode()).hexdigest()

    with open(LICENSE_FILE,"w") as f:
        f.write(f"{expiry}:{sig}:{SCRIPT_ID}")

def check_license():
    if not os.path.exists(LICENSE_FILE):
        return False
    try:
        data=open(LICENSE_FILE).read()
        expiry,sig,saved_id=data.split(":")

        if saved_id!=SCRIPT_ID:
            print("❌ Wrong license for this script!")
            return False

        valid=hashlib.sha256((expiry+"|"+SECRET+"|"+SCRIPT_ID).encode()).hexdigest()

        if sig!=valid:
            os.remove(LICENSE_FILE)
            return False

        if time.time()>int(expiry):
            os.remove(LICENSE_FILE)
            return False

        return True
    except:
        return False

def activate():
    code=generate_code()
    print("[📧] Sending activation code...")
    send_email(code)
    user=input("Enter activation code: ")
    if user==code:
        print("[✔] Activated")
        save_license()
    else:
        print("[x] Wrong code")
        exit()

if not check_license():
    activate()


